\documentclass{article}
\usepackage{amsmath}
\usepackage{amssymb}
\usepackage{amsfonts}
\usepackage{array} % For tables

\begin{document}

\[
\text{5. } f(x) = \frac{x^3-4x}{x^3+x^2-x-1} = \frac{x(x-2)(x+2)}{(x+1)^2(x-1)} = 1 + \frac{-x^2-3x+1}{x^3+x^2-x-1}
\]
\[
D(f) = \mathbb{R} \setminus \{-1, 1\}, \quad \text{zéros: } 0, 2, -2
\]
\[
\begin{array}{|c||c|c|c|c|c|c|c|c|c|}
\hline
x & & -2 & & -1 & & 0 & & 1 & & 2 & \\
\hline
f(x) & + & 0 & - & || & - & 0 & + & || & - & 0 & + \\
\hline
\end{array}
\]
\[
\text{as. hor: } Y=1, \text{ coupée en }
\]
\[
x_{1,2} = \frac{3 \pm \sqrt{13}}{-2} = \frac{-3 \pm \sqrt{13}}{2}
\]

\end{document}

