\begin{document}

2.
(a)
\[ \cos(x) + 2 \frac{\sin^2(x)}{\cos(x)} = 1 \]
\[ \Leftrightarrow \cos^2(x) + 2 \sin^2(x) = \cos(x) \quad (\text{avec } \cos(x) \ne 0) \]
\[ \Leftrightarrow \cos^2(x) + \cos(x) - 2 = 0 \]
\[ \Leftrightarrow \cos(x) = \frac{-1 \pm 3}{2} \quad \text{soit } 1 \text{ ou } -2 \]
\[ \mathbb{L} = \{0\} \]
(b)
\[ 3\alpha = \alpha + 40^\circ + k \cdot 360^\circ \Leftrightarrow \alpha = 20^\circ + k \cdot 180^\circ \quad \text{avec } k = 0 \text{ ou } 1 \]
\[ \text{ou} \]
\[ 3\alpha = 180^\circ - (\alpha + 40^\circ) + k \cdot 360^\circ \Leftrightarrow \alpha = 35^\circ + k \cdot 90^\circ \quad \text{avec } k = 0, 1, 2 \text{ ou } 3 \]

\end{document}

