\begin{cases}
x + y + 2z - w = 10 \\
z - 2w = 5 \\
-z + 2w = -5
\end{cases}
\quad \text{eq1 et eq2: même équation}
\]
\[
w = t \in \mathbb{R}, \quad z = 5 + 2t, \quad y = u \in \mathbb{R}, \quad x = 10 - u - 2(5 + 2t) + t
\]
\[
\Leftrightarrow x = -u - 3t
\]
